/* ============================================================
   إشعار الديسكورد (Webhook) — يصلك عند إضافة منتج للسلة / بدء طلب
   ⚠️ لا يُرسل أي كلمات مرور — فقط اسم المنتج والسعر.
   ضع رابط الويبهوك بين علامتي التنصيص لتفعيله.
   (ملاحظة أمنية: الرابط يظهر في كود الصفحة، فإذا أُسيء استخدامه
    احذف الويبهوك من الديسكورد وأنشئ واحداً جديداً.)
   ============================================================ */
const WEBHOOK_URL = "";   // مثال: "https://discord.com/api/webhooks/xxxx/yyyy"
// وضع السيرفر: يُفعَّل تلقائياً في نسخة Render (index.html يضبط window.__ENTOP_SERVER__)
const SERVER = (typeof window !== "undefined") && !!window.__ENTOP_SERVER__;

function notifyWebhook(title, lines){
  if(!WEBHOOK_URL) return;
  try{
    fetch(WEBHOOK_URL, {
      method:"POST",
      headers:{ "Content-Type":"application/json" },
      body: JSON.stringify({
        username:"ENTOP Store",
        embeds:[{
          title: title,
          description: lines.join("\n"),
          color: 0x7A5BF0,
          footer:{ text:"ENTOP • "+new Date().toLocaleString("ar-SA") }
        }]
      })
    }).catch(()=>{});
  }catch(e){}
}

