/* ============================================================
   التخزين المحلي
   ============================================================ */
const DB = (() => {
  let mem = {}, ok = true;
  try { localStorage.setItem("__t","1"); localStorage.removeItem("__t"); } catch(e){ ok = false; }
  return {
    get(k, d){ try{ const v = ok ? localStorage.getItem(k) : mem[k]; return v ? JSON.parse(v) : d; }catch(e){ return d; } },
    set(k, v){ const s = JSON.stringify(v); if(ok){ try{ localStorage.setItem(k,s); }catch(e){ mem[k]=s; } } else mem[k]=s; },
    del(k){ if(ok){ try{ localStorage.removeItem(k); }catch(e){} } delete mem[k]; }
  };
})();

const Store = {
  users  : () => DB.get("entop_users", []),
  saveUsers: u => DB.set("entop_users", u),
  session: () => DB.get("entop_session", null),
  login  : e => DB.set("entop_session", e),
  logout : () => DB.del("entop_session"),
  me(){ const s = this.session(); return s ? this.users().find(u => u.discord === s) || null : null; },
  update(user){ const all = this.users().map(u => u.discord === user.discord ? user : u); this.saveUsers(all); },
  cart   : () => DB.get("entop_cart", []),
  setCart: c => { DB.set("entop_cart", c); paintCart(); },
  orders : () => DB.get("entop_orders", []),
  setOrders: o => DB.set("entop_orders", o)
};

/* ============================================================
   أدوات مساعدة
   ============================================================ */
const $  = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byCat = c => PRODUCTS.filter(p => p.cat === c);
const find = id => PRODUCTS.find(p => p.id === id);
const money = n => (n === null || n === undefined || n === 0)
  ? `<span class="cur soon">السعر عند الطلب</span>`
  : `<b class="en">${Number(n).toFixed(2)}</b> <span class="cur">${CONFIG.currency}</span>`;

let toastT;
function toast(msg, type = "good"){
  const t = $("#toast");
  t.innerHTML = msg; t.className = `toast show ${type}`;
  clearTimeout(toastT); toastT = setTimeout(() => t.className = "toast", 3000);
}

/* شعارات البنوك (SVG نظيف) */
function bankLogo(key){
  if(key === "barq"){
    return `<svg viewBox="0 0 100 100" class="blogo" aria-label="barq">
      <rect width="100" height="100" rx="26" fill="#0c0c0e"/>
      <path d="M50 16 C53 34 56 38 74 42 C56 46 53 50 50 68 C47 50 44 46 26 42 C44 38 47 34 50 16Z" fill="#fff"/>
      <path d="M69 60 C70.5 68 72 70 80 71.5 C72 73 70.5 75 69 83 C67.5 75 66 73 58 71.5 C66 70 67.5 68 69 60Z" fill="#fff" opacity=".92"/>
    </svg>`;
  }
  // STC Bank
  return `<svg viewBox="0 0 100 100" class="blogo" aria-label="STC Bank">
    <defs><clipPath id="sq"><rect x="6" y="6" width="88" height="88" rx="30"/></clipPath></defs>
    <g clip-path="url(#sq)">
      <rect x="6" y="6" width="88" height="88" fill="#3bb98f"/>
      <path d="M6 6 H94 V52 H6 Z" fill="#4b1f8f"/>
      <text x="50" y="42" text-anchor="middle" font-family="Chakra Petch,Arial,sans-serif" font-size="22" font-weight="700" fill="#fff">STC</text>
      <text x="50" y="78" text-anchor="middle" font-family="Chakra Petch,Arial,sans-serif" font-size="24" font-weight="700" fill="#fff">Bank</text>
    </g>
  </svg>`;
}

/* ============================================================
   بطاقة المنتج
   ============================================================ */
function productCard(p){
  const chip = p.tag
    ? `<span class="chip ${p.tag === "الأكثر مبيعاً" ? "hot" : p.tag === "قريباً" ? "soon-chip" : /special|مميزة|vip/i.test(p.tag) ? "vip" : ""}">${esc(p.tag)}</span>`
    : "";
  const media = p.soon
    ? `<div class="ph soon-ph"><img src="${LOGO_MARK}" class="soon-logo" alt="ENTOP"><span class="soon-big en">SOON</span><span class="soon-ar">قريباً</span></div>`
    : p.img
      ? `<div class="card-img-wrap${p.fit==='contain'?' contain':''}"><img src="${esc(p.img)}" alt="${esc(p.name)}" loading="lazy"></div>`
      : `<div class="ph ph-${p.ph?.tone || 'd'}"><span class="phe">${p.ph?.emoji || "📦"}</span><span>الصورة قريباً</span></div>`;
  const priceHtml = p.soon
    ? `<span class="cur soon">قريباً</span>`
    : `${money(p.price)}${p.old?` <s class="en old">${p.old.toFixed(2)} ${CONFIG.currency}</s>`:""}`;
  const btns = p.soon
    ? `<button class="add soon-btn" disabled>قريباً</button><a class="info" href="#/product/${p.id}">التفاصيل</a>`
    : `<button class="add" data-add="${p.id}">أضف للسلة</button><a class="info" href="#/product/${p.id}">التفاصيل</a>`;
  return `<article class="card${p.soon?' is-soon':''}">
    <div class="card-img">${media}${chip}</div>
    <div class="card-body">
      <h4>${esc(p.name)}</h4>
      <p>${esc(p.desc)}</p>
      <div class="price">${priceHtml}</div>
      <div class="card-btns">${btns}</div>
    </div>
  </article>`;
}

function catBlock(cat){
  const c = CATS[cat], items = byCat(cat);
  if(!items.length) return "";
  return `
  <section class="section wrap" id="sec-${cat}">
    <div class="sec-head">
      <h3><small class="en">${c.sub}</small>${c.title}</h3>
      <a href="#/${cat}">عرض الكل ←</a>
    </div>
    <div class="grid">${items.map(productCard).join("")}</div>
  </section>`;
}

