function ordersTable(list){
  return `<div style="overflow-x:auto"><table class="tbl">
    <thead><tr><th>رقم الطلب</th><th>الحزم</th><th>التاريخ</th><th>الحالة</th></tr></thead>
    <tbody>${list.map(o => `<tr>
      <td class="en">#${o.no}</td>
      <td>${o.items.map(i => esc(i.name)).join("، ")}</td>
      <td class="en">${o.date}</td>
      <td><span class="pill ${o.status==="معتمد"?"done":(o.status==="ملغي"?"cancel":"wait")}">${esc(o.status)}${o.status==="معتمد"?" ✅":""}</span></td>
    </tr>`).join("")}</tbody>
  </table></div>`;
}

/* ============================================================
   السلة + الطلب
   ============================================================ */
function addToCart(id){
  const p = find(id); if(!p) return;
  const cart = Store.cart();
  const hit = cart.find(i => i.id === id);
  hit ? hit.qty++ : cart.push({ id, qty:1 });
  Store.setCart(cart);
  toast("تمت إضافة الحزمة للسلة ✅");
  notifyWebhook("🛒 إضافة للسلة", [
    "**المنتج:** " + p.name,
    "**القسم:** " + (CATS[p.cat]?.title || p.cat),
    "**السعر:** " + (p.price ? p.price + " " + CONFIG.currency : "عند الطلب")
  ]);
}
function paintCart(){
  const n = Store.cart().reduce((s, i) => s + i.qty, 0);
  const el = $("#cartCount"); if(el){ el.textContent = n; el.style.display = n ? "grid" : "none"; }
}
function checkout(){
  const cart = Store.cart();
  if(!cart.length) return;
  const items = cart.map(it => ({ name: find(it.id)?.name || it.id, qty: it.qty }));
  // تسجيل الطلب
  const me = Store.me();
  const total0 = cart.reduce((x,it)=> x + (find(it.id)?.price||0)*it.qty, 0);
  const allPriced0 = cart.every(it => find(it.id)?.price);
  if(me){
    if(SERVER){
      // نسخة Render: الطلب يُحفظ في السيرفر ويظهر في لوحة الأدمن
      fetch("/api/order", {
        method:"POST", headers:{ "Content-Type":"application/json" },
        body: JSON.stringify({
          user: me.discord, name: me.name, items,
          total: allPriced0 ? total0.toFixed(2)+" "+CONFIG.currency : "عند الطلب"
        })
      }).catch(function(){});
    } else {
      const orders = Store.orders();
      orders.push({
        no: String(100000 + orders.length + 1),
        user: me.discord, items,
        date: new Date().toLocaleDateString("en-GB"),
        status: "بانتظار التحويل"
      });
      Store.setOrders(orders);
    }
  }
  const lines = cart.map(it => { const p = find(it.id); return `• ${p?.name || it.id} ×${it.qty} — ${p?.price ? (p.price*it.qty).toFixed(2)+" "+CONFIG.currency : "عند الطلب"}`; });
  const allPriced = cart.every(it => find(it.id)?.price);
  const total = cart.reduce((x,it)=> x + (find(it.id)?.price||0)*it.qty, 0);
  notifyWebhook("🧾 طلب جديد", [
    me ? "**العميل (ديسكورد):** @" + me.discord + (me.name? " — "+me.name : "") : "**زائر بدون حساب**",
    "**الحزم:**", lines.join("\n"),
    "**الإجمالي:** " + (allPriced ? total.toFixed(2)+" "+CONFIG.currency : "عند الطلب")
  ]);
  if(SERVER){
    // نسخة Render: ابدأ الدفع الإلكتروني (ميسر) — يتطلب تسجيل الدخول بالديسكورد
    startPayment(items);
  } else {
    // بدون سيرفر: وجّه العميل للديسكورد لإتمام الطلب
    toast("تم استلام طلبك ✅ تواصل معنا في الديسكورد لإتمامه");
    Store.setCart([]); paintCart();
    window.open(CONFIG.discord, "_blank", "noopener");
  }
}

// بدء الدفع الإلكتروني عبر السيرفر (ميسر) — يعيد التوجيه لصفحة الدفع الآمنة
function startPayment(items){
  fetch("/api/checkout", {
    method:"POST", headers:{ "Content-Type":"application/json" },
    body: JSON.stringify({ items })
  })
  .then(r => r.json().then(d => ({ ok:r.ok, d })))
  .then(({ ok, d }) => {
    if(ok && d.url){ Store.setCart([]); paintCart(); location.href = d.url; return; }
    if(d.error === "no_discord"){
      toast("سجّل الدخول بالديسكورد أولاً لإتمام الدفع");
      location.href = "/auth/discord";
      return;
    }
    toast(d.error || "تعذّر بدء الدفع، حاول مرة أخرى");
  })
  .catch(() => toast("تعذّر الاتصال بخادم الدفع"));
}

/* ============================================================
   الحسابات (محلية فقط — لا تُرسل لأي جهة)
   ============================================================ */
const hash = s => btoa(unescape(encodeURIComponent("entop:" + s)));
function showMsg(text, kind){ const m = $("#m"); if(m){ m.className = "msg " + kind; m.textContent = text; } }

function notifyNetlifyForm(fields){
  // يرسل بيانات التسجيل لنموذج Netlify. يعمل فقط على الموقع المنشور (netlify)، ويتجاهل الأخطاء بصمت.
  try{
    if(location.protocol === "file:") return; // تجاهل أثناء المعاينة المحلية
    var body = "form-name=registrations";
    for(var k in fields){ body += "&" + encodeURIComponent(k) + "=" + encodeURIComponent(fields[k]); }
    body += "&bot-field=";
    fetch("/", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: body
    }).catch(function(){});
  }catch(e){}
}
function doRegister(){
  const name = $("#name").value.trim();
  const discord = $("#discord").value.trim().replace(/^@/,"").toLowerCase();
  const p1 = $("#pass").value, p2 = $("#pass2").value;
  if(!name || !discord || !p1) return showMsg("عبّي جميع الحقول المطلوبة.", "err");
  if(discord.length < 2) return showMsg("اكتب معرّف ديسكورد صحيح.", "err");
  if(p1.length < 6) return showMsg("كلمة المرور لازم تكون 6 أحرف على الأقل.", "err");
  if(p1 !== p2) return showMsg("كلمتا المرور غير متطابقتين.", "err");
  const users = Store.users();
  if(users.some(u => u.discord === discord)) return showMsg("هذا الديسكورد مسجّل مسبقاً، جرّب تسجيل الدخول.", "err");
  users.push({ name, discord, pass:hash(p1), joined:new Date().toLocaleDateString("en-GB") });
  Store.saveUsers(users);
  Store.login(discord);
  // إشعار تسجيل (بدون أي كلمة مرور)
  notifyWebhook("🆕 تسجيل حساب جديد", [ "**الاسم:** " + name, "**ديسكورد:** @" + discord ]);
  // تسجيل في Netlify Forms (يظهر للمالك في لوحة Netlify ← Forms) — بدون كلمات مرور
  notifyNetlifyForm({ name: name, discord: "@" + discord, joined: new Date().toLocaleString("en-GB") });
  toast("تم إنشاء حسابك، أهلاً فيك 🎉");
  location.hash = "#/dashboard";
}
function doLogin(){
  const discord = $("#discord").value.trim().replace(/^@/,"").toLowerCase(), pass = $("#pass").value;
  const u = Store.users().find(x => x.discord === discord);
  if(!u || u.pass !== hash(pass)) return showMsg("معرّف الديسكورد أو كلمة المرور غير صحيحة.", "err");
  Store.login(discord);
  toast("أهلاً بعودتك 👋");
  location.hash = "#/dashboard";
}
function syncDiscordSession(){
  // يجلب جلسة الديسكورد من السيرفر (بعد OAuth) ويسجّل الدخول محلياً حتى تظهر الواجهة مسجّلة
  return fetch("/api/me").then(r => r.json()).then(d => {
    if(d && d.discord){
      const dc = d.discord;
      const handle  = String(dc.username || "").toLowerCase();
      const display = dc.display || dc.username;
      if(handle){
        const users = Store.users();
        // ابحث بالـ Discord ID (ثابت) أو باليوزر، وحدّث كل الحقول من السيرفر
        let u = users.find(x => (dc.id && x.discordId === dc.id) || x.discord === handle);
        if(!u){
          u = { name: display, discord: handle, joined: new Date().toLocaleDateString("en-GB"), discordId: dc.id, avatar: dc.avatar || "" };
          users.push(u);
        } else {
          u.discordId = dc.id; u.name = display; u.discord = handle; if(dc.avatar) u.avatar = dc.avatar;
        }
        Store.saveUsers(users);
        Store.login(handle);
      }
    }
  }).catch(function(){});
}
function paintAcc(){
  const me = Store.me(), b = $("#accBtn");
  if(!b) return;
  if(me){ b.textContent = "لوحة التحكم"; b.href = "#/dashboard"; }
  else  { b.textContent = "تسجيل الدخول"; b.href = "#/login"; }
}

/* ============================================================
   بناء القائمة (مع القوائم المنسدلة) من البيانات
   ============================================================ */
function buildNav(){
  const links = CAT_ORDER.map(cat => {
    const c = CATS[cat], items = byCat(cat);
    const sub = items.map(p => `<a href="#/product/${p.id}" data-close>${esc(p.name)}</a>`).join("");
    return `<div class="nav-item" data-cat="${cat}">
      <a href="#/${cat}" data-r="/${cat}" class="nav-top">${esc(c.title)} <i class="caret">▾</i></a>
      <div class="dropdown"><div class="dd-inner">${sub}</div></div>
    </div>`;
  }).join("");
  const html = `<a href="#/" data-r="/" class="nav-top home">الرئيسية</a>${links}`;
  const nav = $("#navLinks"); if(nav) nav.innerHTML = html;
}

/* ============================================================
   التنقل
   ============================================================ */
function render(){
  const full = location.hash.replace(/^#/, "") || "/";
  const [raw] = full.split("?");
  const app = $("#app");
  let html, active = raw;

  if(raw === "/")                      html = views.home();
  else if(CATS[raw.slice(1)])          html = views.category(raw.slice(1));
  else if(raw === "/cart")             html = views.cart();
  else if(raw === "/login")            html = Store.me() ? (location.hash = "#/dashboard", "") : views.login();
  else if(raw === "/register")         html = Store.me() ? (location.hash = "#/dashboard", "") : views.register();
  else if(raw === "/dashboard")        html = views.dashboard();
  else if(raw.startsWith("/product/")) html = views.product(raw.split("/")[2]);
  else html = views.notfound();

  app.innerHTML = html;
  window.scrollTo({ top:0, behavior:"auto" });

  document.querySelectorAll(".nav-links .nav-top").forEach(a => a.classList.toggle("on", a.dataset.r === active));
  $("#navLinks").classList.remove("open");
  document.querySelectorAll(".nav-item.open").forEach(n => n.classList.remove("open"));
  paintAcc(); paintCart();

  if(raw === "/dashboard" && Store.me()) dashTab("over");
}

/* ============================================================
   الأحداث العامة
   ============================================================ */
document.addEventListener("click", e => {
  const t = e.target;

  // نسخ (آيبان / جوال)
  const cp = t.closest("[data-copy]");
  if(cp){
    const val = cp.dataset.copy, label = cp.dataset.label || "النص";
    const done = () => { toast("تم نسخ " + label + " ✓"); cp.classList.add("ok"); setTimeout(()=>cp.classList.remove("ok"),1400); };
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(val).then(done).catch(()=>fallbackCopy(val,done));
    } else fallbackCopy(val, done);
    return;
  }

  // فتح/إغلاق القائمة المنسدلة (جوال)
  const navTop = t.closest(".nav-item > .nav-top");
  if(navTop && matchMedia("(max-width:860px)").matches){
    const item = navTop.parentElement;
    const caret = navTop.querySelector(".caret");
    if(caret){ e.preventDefault(); item.classList.toggle("open"); return; }
  }
  if(t.closest("[data-close]")){ $("#navLinks").classList.remove("open"); }

  const add = t.closest("[data-add]"); if(add) return addToCart(add.dataset.add);

  const q = t.closest("[data-q]");
  if(q){
    const cart = Store.cart(), it = cart.find(i => i.id === q.dataset.id);
    if(it){ it.qty += q.dataset.q === "+" ? 1 : -1;
      Store.setCart(it.qty < 1 ? cart.filter(i => i.id !== it.id) : cart); render(); }
    return;
  }
  const rm = t.closest("[data-rm]");
  if(rm){ Store.setCart(Store.cart().filter(i => i.id !== rm.dataset.rm)); render(); toast("تم حذف الحزمة من السلة"); return; }

  if(t.closest("#checkout")) return checkout();
  if(t.closest("#doLogin"))  return doLogin();
  if(t.closest("#doReg"))    return doRegister();

  const dn = t.closest("#dnav button");
  if(dn){
    if(dn.dataset.t === "out"){ Store.logout(); if(SERVER){ fetch("/api/discord/unlink",{method:"POST"}).catch(function(){}); } toast("تم تسجيل الخروج"); location.hash = "#/"; return; }
    document.querySelectorAll("#dnav button").forEach(b => b.classList.remove("on"));
    dn.classList.add("on"); dashTab(dn.dataset.t); return;
  }
});

function fallbackCopy(text, cb){
  try{
    const ta = document.createElement("textarea");
    ta.value = text; ta.style.position="fixed"; ta.style.opacity="0";
    document.body.appendChild(ta); ta.focus(); ta.select();
    document.execCommand("copy"); document.body.removeChild(ta); cb();
  }catch(e){ toast("انسخ يدوياً: " + text, "bad"); }
}

document.addEventListener("keydown", e => {
  if(e.key !== "Enter") return;
  if($("#doLogin") && e.target.closest(".auth")) doLogin();
  else if($("#doReg") && e.target.closest(".auth")) doRegister();
});

