/* ============================================================
   الخلفية ثلاثية الأبعاد (Three.js) — شبكة نيون + جزيئات
   بألوان شعار ENTOP. تعمل خلف المحتوى، ولا تمسّ تأثير الماوس.
   إذا تعذّر تحميل المكتبة → خلفية متدرجة متحركة احتياطية.
   ============================================================ */
function init3DBackground(){
  const host = document.getElementById("bg3d");
  if(!host) return;
  if(typeof THREE === "undefined"){ host.classList.add("fallback"); return; }
  if(matchMedia("(prefers-reduced-motion:reduce)").matches){ host.classList.add("fallback"); return; }

  const C = { teal:0x1FE3B6, blue:0x2F8BF2, purple:0x7A5BF0, pink:0xE51FC4 };
  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0x05070E, 0.021);

  const camera = new THREE.PerspectiveCamera(70, innerWidth/innerHeight, 0.1, 160);
  camera.position.set(0, 0, 11);

  const renderer = new THREE.WebGLRenderer({ antialias:true, alpha:true, powerPreference:"high-performance" });
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.8));
  renderer.setSize(innerWidth, innerHeight);
  host.appendChild(renderer.domElement);

  // نجوم ثلاثية الأبعاد موزّعة في الفضاء (بدون أي شبكة/مربعات)
  const COUNT = 1700;
  const geo = new THREE.BufferGeometry();
  const pos = new Float32Array(COUNT*3), col = new Float32Array(COUNT*3);
  const palette = [C.teal, C.blue, C.purple, C.pink, 0xffffff].map(h => new THREE.Color(h));
  for(let i=0;i<COUNT;i++){
    const r = 16 + Math.random()*52;
    const th = Math.random()*Math.PI*2, ph = Math.acos(2*Math.random()-1);
    pos[i*3]   = r*Math.sin(ph)*Math.cos(th);
    pos[i*3+1] = r*Math.sin(ph)*Math.sin(th);
    pos[i*3+2] = r*Math.cos(ph);
    const c = palette[(Math.random()*palette.length)|0];
    col[i*3]=c.r; col[i*3+1]=c.g; col[i*3+2]=c.b;
  }
  geo.setAttribute("position", new THREE.BufferAttribute(pos,3));
  geo.setAttribute("color", new THREE.BufferAttribute(col,3));
  const pmat = new THREE.PointsMaterial({ size:0.15, vertexColors:true, transparent:true, opacity:0.95, depthWrite:false, blending:THREE.AdditiveBlending });
  const stars = new THREE.Points(geo, pmat);
  scene.add(stars);

  // شعار ENTOP يطوف ويلف في الخلفية (دمج إضافي: يختفي الأسود ويبقى توهّج الشعار)
  const LOGO3D = "data:image/jpeg;base64,";
  const tex = new THREE.TextureLoader().load(LOGO3D);
  tex.minFilter = THREE.LinearFilter;
  const logoMat = () => new THREE.MeshBasicMaterial({ map:tex, transparent:true, opacity:0.95, depthWrite:false, blending:THREE.AdditiveBlending });

  // الشعار المركزي + حلقتان دائريتان متوهّجتان (تشبه الإطار الدائري)
  const core = new THREE.Group();
  const LW = 6.6, LH = LW*265/300;
  const logo = new THREE.Mesh(new THREE.PlaneGeometry(LW, LH), logoMat());
  core.add(logo);
  const ring1 = new THREE.Mesh(new THREE.TorusGeometry(4.7, 0.05, 16, 140),
    new THREE.MeshBasicMaterial({ color:C.teal, transparent:true, opacity:0.5, blending:THREE.AdditiveBlending, depthWrite:false }));
  const ring2 = new THREE.Mesh(new THREE.TorusGeometry(5.05, 0.035, 16, 140),
    new THREE.MeshBasicMaterial({ color:C.pink, transparent:true, opacity:0.45, blending:THREE.AdditiveBlending, depthWrite:false }));
  core.add(ring1); core.add(ring2);
  core.position.set(0, 0, -2);
  scene.add(core);

  // شعارات ENTOP صغيرة تطوف حول المركز
  const orbiters = [];
  for(let i=0;i<6;i++){
    const sz = 1.15 + (i%2)*0.45;
    const m = new THREE.Mesh(new THREE.PlaneGeometry(sz, sz*265/300), logoMat());
    m.userData = { ang:(i/6)*Math.PI*2, rad:6.8 + (i%2)*1.6, y:(Math.random()-0.5)*4.8, sp:0.14 + Math.random()*0.16, spin:(Math.random()<0.5?-1:1)*(0.25+Math.random()*0.3) };
    scene.add(m); orbiters.push(m);
  }

  let mx=0, my=0;
  addEventListener("pointermove", e => {
    mx = (e.clientX/innerWidth - 0.5);
    my = (e.clientY/innerHeight - 0.5);
  }, { passive:true });

  addEventListener("resize", () => {
    camera.aspect = innerWidth/innerHeight; camera.updateProjectionMatrix();
    renderer.setSize(innerWidth, innerHeight);
  });

  let run = true;
  document.addEventListener("visibilitychange", ()=>{ run = !document.hidden; if(run) animate(); });

  const clock = new THREE.Clock();
  function animate(){
    if(!run) return;
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();
    stars.rotation.y = t*0.015; stars.rotation.x = t*0.006;
    logo.position.y = Math.sin(t*0.6)*0.25;
    logo.rotation.z = Math.sin(t*0.4)*0.07;
    const pulse = 1 + Math.sin(t*1.2)*0.03; logo.scale.set(pulse, pulse, 1);
    ring1.rotation.z = t*0.25; ring1.rotation.x = 0.5 + Math.sin(t*0.3)*0.15;
    ring2.rotation.z = -t*0.3; ring2.rotation.y = t*0.2;
    core.rotation.y = Math.sin(t*0.15)*0.12;
    orbiters.forEach(o => {
      const a = o.userData.ang + t*o.userData.sp;
      o.position.set(Math.cos(a)*o.userData.rad,
                     o.userData.y + Math.sin(t*0.6 + o.userData.ang)*0.7,
                     -2 + Math.sin(a)*o.userData.rad);
      o.rotation.z = t*o.userData.spin;
    });
    // ميلان خفيف للكاميرا (يكمّل التأثير ولا يغيّر مؤشر الماوس)
    camera.position.x += (mx*2.4 - camera.position.x)*0.04;
    camera.position.y += (-my*1.8 - camera.position.y)*0.04;
    camera.lookAt(0, 0, -2);
    renderer.render(scene, camera);
  }
  animate();
}
window.addEventListener("load", init3DBackground);

/* ============================================================
   تأثير الشرر المتحرك مع الماوس (Firework Cursor)
   يشتغل على الأجهزة اللي فيها ماوس فقط، ويتوقف تلقائياً على الجوال
   ============================================================ */
const CURSOR_FX = {
  on        : true,   // false لإيقاف التأثير نهائياً
  rate      : 3,      // عدد الشرر مع كل حركة (1-6)
  size      : 16,     // حجم الشرارة
  lifetime  : 62,     // مدة بقاء الشرارة (فريم)
  gravity   : 0.045,  // الجاذبية
  spread    : 1.5,    // تشتت الشرر
  max       : 520,    // أقصى عدد شرر في نفس اللحظة
  burst     : 46,     // عدد الشرر عند الضغط بالماوس
  glow      : 0.85,   // قوة التوهج
  colors    : ["#1FE3B6","#2F8BF2","#7A5BF0","#E51FC4","#EAF1FB"]
};

(function fireworkCursor(){
  if(!CURSOR_FX.on) return;
  const fine = matchMedia("(hover:hover) and (pointer:fine)").matches;
  const calm = matchMedia("(prefers-reduced-motion:reduce)").matches;
  if(!fine || calm) return;                       // جوال أو وضع تقليل الحركة

  const cv = document.createElement("canvas");
  cv.id = "fxCursor";
  document.body.appendChild(cv);
  const ctx = cv.getContext("2d", { alpha:true });

  let W = 0, H = 0, dpr = 1;
  function resize(){
    dpr = Math.min(devicePixelRatio || 1, 2);
    W = innerWidth; H = innerHeight;
    cv.width = W * dpr; cv.height = H * dpr;
    cv.style.width = W + "px"; cv.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  resize();
  addEventListener("resize", resize);

  /* صور توهج جاهزة لكل لون — أسرع بكثير من الرسم المباشر */
  const sprites = CURSOR_FX.colors.map(col => {
    const s = document.createElement("canvas"); s.width = s.height = 64;
    const g = s.getContext("2d");
    const rad = g.createRadialGradient(32,32,0,32,32,32);
    rad.addColorStop(0,   col);
    rad.addColorStop(.35, col + "AA");
    rad.addColorStop(1,   col + "00");
    g.fillStyle = rad; g.beginPath(); g.arc(32,32,32,0,Math.PI*2); g.fill();
    return s;
  });

  const parts = [];
  let mx = -999, my = -999, px = -999, py = -999, alive = false;

  function spawn(x, y, n, power){
    for(let i = 0; i < n && parts.length < CURSOR_FX.max; i++){
      const a = Math.random() * Math.PI * 2;
      const sp = (Math.random() * CURSOR_FX.spread + .2) * power;
      parts.push({
        x, y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp - .35,
        life: CURSOR_FX.lifetime * (.6 + Math.random() * .6),
        age: 0,
        r: CURSOR_FX.size * (.35 + Math.random() * .75),
        s: sprites[(Math.random() * sprites.length) | 0]
      });
    }
  }

  addEventListener("pointermove", e => {
    mx = e.clientX; my = e.clientY;
    if(!alive){ px = mx; py = my; alive = true; }
    const d = Math.hypot(mx - px, my - py);
    px = mx; py = my;
    spawn(mx, my, Math.min(CURSOR_FX.rate + (d > 22 ? 2 : 0), 6), 1);
  }, { passive:true });

  addEventListener("pointerdown", e => spawn(e.clientX, e.clientY, CURSOR_FX.burst, 2.6), { passive:true });
  document.documentElement.addEventListener("pointerleave", () => alive = false);

  let running = true;
  document.addEventListener("visibilitychange", () => {
    running = !document.hidden;
    if(running) requestAnimationFrame(loop);
  });

  function loop(){
    if(!running) return;
    ctx.clearRect(0, 0, W, H);
    ctx.globalCompositeOperation = "lighter";
    for(let i = parts.length - 1; i >= 0; i--){
      const p = parts[i];
      p.age++;
      if(p.age >= p.life){ parts.splice(i, 1); continue; }
      p.vx *= .955; p.vy = p.vy * .955 + CURSOR_FX.gravity;
      p.x += p.vx; p.y += p.vy;
      const t = 1 - p.age / p.life;
      ctx.globalAlpha = t * t * CURSOR_FX.glow;
      const r = p.r * (.35 + t);
      ctx.drawImage(p.s, p.x - r, p.y - r, r * 2, r * 2);
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();

window.__ENTOP_OK = true;

window.galPick=function(btn){var m=document.getElementById("galMain");if(!m)return;m.src=btn.querySelector("img").src;var th=btn.parentElement.querySelectorAll(".gthumb");for(var i=0;i<th.length;i++)th[i].classList.remove("on");btn.classList.add("on");};
